def sm(g,k=50,pr=None): return (g.sum()+k*pr)/(g.count()+k)
for name,(a,b) in harness.FOLDS.items():
    pr=a[T].mean()
    allr=a.groupby('primacy_agency_code')[T].apply(sm,pr=pr)
    n=len(a)
    rec={f:a.iloc[int(n*(1-f)):].groupby('primacy_agency_code')[T].apply(sm,pr=a.iloc[int(n*(1-f)):][T].mean()) for f in (0.5,0.25,0.1)}
    act=b.groupby('primacy_agency_code')[T].agg(['mean','size'])
    df=pd.concat([act,allr.rename('all')]+[r.rename('rec%s'%f) for f,r in rec.items()],axis=1).dropna()
    w=df['size']
    def wc(x,y): 
        mx=np.average(x,weights=w);my=np.average(y,weights=w)
        return np.average((x-mx)*(y-my),weights=w)/np.sqrt(np.average((x-mx)**2,weights=w)*np.average((y-my)**2,weights=w))
    print(name,{c:round(wc(df[c],df['mean']),3) for c in df.columns[2:]})
EOF
