"""Paired bootstrap on saved validation predictions of this run's own trials (diagnostic)."""
import json, glob, numpy as np, pandas as pd
from sklearn.metrics import roc_auc_score
R={}
for f in glob.glob('trials/*/result.json'):
    r=json.load(open(f))
    if r.get('status')=='ok' and r['mode']=='validation': R[r['id'][:8]]=(r['auc'],pd.read_csv(f.replace('result.json','validation.csv.gz')))
for k,(a,_) in sorted(R.items(),key=lambda kv:kv[1][0]): print(k,round(a,5))
rng=np.random.RandomState(0); y=next(iter(R.values()))[1].y.to_numpy(); n=len(y)
idx=[rng.randint(0,n,n) for _ in range(400)]
def boot(k): 
    p=R[k][1].p.to_numpy(); return np.array([roc_auc_score(y[i],p[i]) for i in idx])
B={k:boot(k) for k in R}
best=max(R,key=lambda k:R[k][0])
print('best',best,'AUC 95%% bootstrap CI: %.4f-%.4f (se %.4f)'%(np.percentile(B[best],2.5),np.percentile(B[best],97.5),B[best].std()))
for k in R:
    if k!=best:
        d=B[best]-B[k]; print('best - %s: %.4f  CI %.4f..%.4f  P(diff>0)=%.2f'%(k,R[best][0]-R[k][0],np.percentile(d,2.5),np.percentile(d,97.5),(d>0).mean()))
EOF
