"""Nine rolling training-only folds (cutoffs 2004..2012, 2-year embargoed scored window): higher-power config comparison."""
import sys,copy; sys.path.insert(0,'diag')
import numpy as np, pandas as pd, harness, cand
from sklearn.metrics import roc_auc_score
T=harness.T; tr=harness.tr; base=copy.deepcopy(cand.CFG); F=[]
for cut in range(2004,2013):
    c=pd.Timestamp('%d-01-01'%cut); e=c+pd.DateOffset(years=2)
    F.append((tr[tr.t<c],tr[(tr.t>=c)&(tr.t<e)&(tr.pe<c)]))
def go(label,**kw):
    cand.CFG=copy.deepcopy(base)
    for k,v in kw.items():
        if k=='params': cand.CFG['params'].update(v)
        else: cand.CFG[k]=v
    out=[]
    for a,b in F:
        st=cand.fit(a[harness.FEATS].reset_index(drop=True),a[T].to_numpy(),seed=42,threads=5)
        out.append(roc_auc_score(b[T],st['model'].predict_proba(cand.prepare(st,b[harness.FEATS].reset_index(drop=True)))[:,1]))
    print('%-26s'%label,' '.join('%.3f'%v for v in out),' mean=%.4f'%np.mean(out),flush=True); return out
